/* Shared council achievements: alternative development routes, sustained for three turns. */
const Objectives=(()=>{
const names={prosperity:'🌱 Thriving kingdom',learning:'📚 Center of learning',diplomacy:'🤝 Trusted partners',security:'🛡 Secure homeland'};
function upgrade(s){s.countries.forEach(c=>{const owned=s.cells.filter(x=>x.land&&x.country===c.id);c.foundation=c.foundation||{cells:owned.length,settlements:owned.filter(x=>x.buildings.includes('city')||x.buildings.includes('village')).length};c.ambition=c.ambition||'prosperity';c.tradeReceived=c.tradeReceived||0;c.badges=c.badges||{};c.goalStreak=c.goalStreak||Object.fromEntries(Object.keys(names).map(k=>[k,0]));});return s;}
function progress(s,c){const cells=s.cells.filter(x=>x.land&&x.country===c.id),population=cells.reduce((n,x)=>n+x.population,0),count=type=>cells.filter(x=>x.buildings.includes(type)).length,settlements=cells.filter(x=>x.buildings.includes('city')||x.buildings.includes('village')).length,allies=s.countries.filter(x=>x.id!==c.id&&Game.relation(s,c.id,x.id)==='ally').length,enemies=s.countries.filter(x=>x.id!==c.id&&Game.relation(s,c.id,x.id)==='enemy').length,army=s.regiments.filter(r=>r.country===c.id&&r.troops>0),troops=army.reduce((n,r)=>n+r.troops,0),discoveries=Object.values(c.tech).reduce((n,x)=>n+x,0),metric=(label,value,target)=>({label,value,target,met:value>=target}),healthy=!c.lastShortage;
return {
prosperity:{description:'Keep people happy and fed. Grow settlements OR build trading connections.',metrics:[metric('Morale',Math.floor(c.morale),75),metric('Treasury',Math.floor(c.stock.money),Math.max(300,Math.ceil(population*.12))),metric('Food reserve',Math.floor(c.stock.food),Math.max(40,Math.ceil(population/55)))],route:metric('New settlements (2) OR received shipments (6)',Math.max((settlements-c.foundation.settlements)/2,c.tradeReceived/6),1),routeText:`${Math.max(0,settlements-c.foundation.settlements)} / 2 new settlements · ${c.tradeReceived} / 6 received shipments`,extra:healthy,extraText:'No food or money shortage this turn'},
learning:{description:'Fund useful discoveries. Build schools OR spread research across more discoveries.',metrics:[metric('Learning level',Math.floor(c.literacy),50),metric('Discoveries',discoveries,6),metric('Morale',Math.floor(c.morale),60)],route:metric('Schools (2) OR discoveries (9)',Math.max(count('school')/2,discoveries/9),1),routeText:`${count('school')} / 2 schools · ${discoveries} / 9 discoveries`,extra:healthy,extraText:'No food or money shortage this turn'},
diplomacy:{description:'Keep peace while exchanging goods. Build a wide alliance OR a strong trade network.',metrics:[metric('Allies',allies,2),metric('Received shipments',c.tradeReceived,3),metric('Morale',Math.floor(c.morale),60)],route:metric('Allies (3) OR received shipments (6)',Math.max(allies/3,c.tradeReceived/6),1),routeText:`${allies} / 3 allies · ${c.tradeReceived} / 6 received shipments`,extra:enemies===0&&healthy,extraText:'At peace with everyone, with no food or money shortage'},
security:{description:'Protect a supplied army and retain your starting amount of land. Build forts OR improve armaments.',metrics:[metric('Troops',troops,60),metric('Owned land cells',cells.length,c.foundation.cells),metric('Morale',Math.floor(c.morale),65)],route:metric('Forts (2) OR military discoveries (3)',Math.max(count('fort')/2,c.tech.arms/3),1),routeText:`${count('fort')} / 2 forts · ${c.tech.arms} / 3 military discoveries`,extra:healthy&&army.length>0&&army.every(r=>r.readiness>=80&&r.supply>=Math.ceil(r.troops*.1)&&Military.connected(s,r,Game.relation)),extraText:'Every regiment connected to supply, food stocked, readiness at least 80; no national shortage'}
};}
function finish(s,notes){for(const c of s.countries)for(const [key,p] of Object.entries(progress(s,c))){if(c.badges[key])continue;const met=p.extra&&p.route.met&&p.metrics.every(m=>m.met);c.goalStreak[key]=met?c.goalStreak[key]+1:0;if(c.goalStreak[key]>=3){c.badges[key]=s.turn;notes.push(`${c.name} earned ${names[key]} by meeting its goals for three turns. The campaign continues; other kingdoms can succeed too.`);}}}
function validate(s){for(const c of s.countries){if(!names[c.ambition]||!Number.isInteger(c.tradeReceived)||c.tradeReceived<0||!Number.isInteger(c.foundation?.cells)||c.foundation.cells<0||!Number.isInteger(c.foundation?.settlements)||c.foundation.settlements<0||Object.keys(names).some(k=>!Number.isInteger(c.goalStreak?.[k])||c.goalStreak[k]<0||c.goalStreak[k]>3)||Object.entries(c.badges).some(([k,v])=>!names[k]||!Number.isInteger(v)||v<1||v>s.turn))throw Error('Invalid kingdom goals.');}}
return {names,upgrade,progress,finish,validate};})();
